// Rebuilds src/lib/annexIII/entries.generated.ts from the CosIng export in data/cosing.
// Run with:  npm run build:annex3   (needs Node 22.6+ or newer; no other tools)

import { readFileSync, writeFileSync } from 'node:fs';
import { buildAnnexData } from '../src/lib/annexIII/parse.ts';

const source = new URL('../data/cosing/COSING_Annex_III_v2.csv', import.meta.url);
const target = new URL('../src/lib/annexIII/entries.generated.ts', import.meta.url);

const data = buildAnnexData(readFileSync(source, 'utf8'));
const body = [
    '// GENERATED by scripts/buildAnnexIII.ts from data/cosing/COSING_Annex_III_v2.csv. Do not edit by hand: run `npm run build:annex3`.',
    '// Source: European Commission CosIng database, Annex III of Regulation (EC) No 1223/2009.',
    "import type { AnnexData } from './parse';",
    '',
    `export const ANNEX_III: AnnexData = ${JSON.stringify(data, null, 1)};`,
    '',
].join('\n');
writeFileSync(target, body);
const numeric = data.entries.filter(e => e.scopes.length).length;
const declare = data.entries.filter(e => e.declare).length;
console.log(`Wrote ${data.entries.length} entries (${numeric} with numeric limits, ${declare} with label thresholds), CosIng update ${data.updated}.`);
